        dx = clamp(tx - sx)
        dy = clamp(ty - sy)
        nx = sx + dx
        ny = sy + dy
        if (nx, ny) in obstacle_set or nx < 0 or nx >= w or ny < 0 or ny >= h:
            return [0, 0]
        return [int(dx), int(dy)]

    dx, dy = best_move[1]
    return [int(dx), int(dy)]

